  "review_info": [
    {
      "review_date": "2019-10-17 02:27:02",
      "review_stars": 5.0,
      "review_text": "Absolutely wonderful way to spice up any event! Mario and his crew knock it out of the park!  The margarita truck added such a fun atmosphere to my party! Highly recommend the cucumber jalapeno margarita!  I would book this for any future event here!  Thank you Rasta Rita!"
    },
    {
      "review_date": "2018-07-12 16:42:49",
      "review_stars": 5.0,
      "review_text": "Rasta Rita was used for a military event and was such a hit! Mario is super friendly to work with and is always willing to help out.  The truck was so fun and the drinks were delicious! Everyone at our event had such a fun time interacting with the truck and sipping the yummy margaritas.  What an amazing concept!  We are using the truck again this year as it has been such a hot item!!"
    },
    {
      "review_date": "2017-07-31 03:14:02",
      "review_stars": 5.0,
      "review_text": "Mario was freaking amazing !!!! He was so charismatic and instinctful !! He's defiantly a one man show !! I would refer him for any event !! He bartender my friend Pilar wedding and did a amazing job !!!"
    }
  ],
  "state": "CA"
}

